        let data = res.data
        assert.equal(data.BaseResponse.Ret, 0, res)
        this.PROP.baseRequest.Skey = this.PROP.skey = data.SKey || this.PROP.skey
        this.updateSyncKey(data.SyncKey)
        Object.assign(this.user, data.User)
